import { ChevronDown, ChevronRight } from 'lucide-react'
import { useEffect, useState } from 'react'

import { cx } from '~/lib/cx'
import { DismissableLayer } from '~/components/primitives/dismissable-layer'

import styles from './cascader.module.scss'

export type CascaderOption = {
  value: string
  label: string
  children?: CascaderOption[]
  disabled?: boolean
}

export interface CascaderProps {
  options: CascaderOption[]
  value?: string[]
  defaultValue?: string[]
  onChange?: (value: string[], selected: CascaderOption[]) => void
  label?: string
  placeholder?: string
  disabled?: boolean
  className?: string
  id?: string
  separator?: string
}

function findOption(options: CascaderOption[], value: string): CascaderOption | undefined {
  return options.find((option) => option.value === value)
}

function resolve(options: CascaderOption[], path: string[]): CascaderOption[] {
  const result: CascaderOption[] = []
  let current = options
  for (const value of path) {
    const option = findOption(current, value)
    if (!option) break
    result.push(option)
    current = option.children ?? []
  }
  return result
}

/** Multi-level select for dependent options. */
export function Cascader({
  options,
  value,
  defaultValue = [],
  onChange,
  label,
  placeholder = 'Select an option',
  disabled = false,
  className,
  id,
  separator = ' / ',
}: CascaderProps) {
  const [open, setOpen] = useState(false)
  const [internal, setInternal] = useState<string[]>(defaultValue)
  const [path, setPath] = useState<string[]>(value ?? defaultValue)

  const selected = value ?? internal
  const selectedOptions = resolve(options, selected)

  useEffect(() => {
    if (!open) return
    setPath(value ?? internal)
  }, [open, value, internal])

  const choose = (option: CascaderOption) => {
    if (option.disabled) return
    const nextPath = [...path, option.value]
    setPath(nextPath)
    if (option.children?.length) return
    const nextValue = nextPath
    if (value === undefined) setInternal(nextValue)
    onChange?.(nextValue, resolve(options, nextValue))
    setOpen(false)
  }

  const columns: CascaderOption[][] = []
  let current = options
  for (const valuePart of path) {
    if (!current.length) break
    columns.push(current)
    const next = findOption(current, valuePart)
    current = next?.children ?? []
  }
  if (current.length) columns.push(current)

  return (
    <div className={cx(styles.root, className)}>
      {label ? <span className={styles.label}>{label}</span> : null}
      <button
        id={id}
        type="button"
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={cx(styles.trigger)}
        onClick={() => setOpen((current) => !current)}
      >
        <span className={selectedOptions.length ? undefined : styles.placeholder}>
          {selectedOptions.length
            ? selectedOptions.map((option) => option.label).join(separator)
            : placeholder}
        </span>
        <ChevronDown className={cx(styles.chevron, open && styles.open)} aria-hidden />
      </button>

      {open ? (
        <DismissableLayer onDismiss={() => setOpen(false)}>
          <div className={styles.panel} role="listbox" aria-label={label ?? placeholder}>
            {columns.map((column, depth) => (
              <ul key={depth} className={styles.column} role="group">
                {column.map((option) => {
                  const active = path[depth] === option.value
                  const isSelected =
                    selected[depth] === option.value && depth === selected.length - 1
                  return (
                    <li key={option.value}>
                      <button
                        type="button"
                        role="option"
                        aria-selected={isSelected}
                        disabled={option.disabled}
                        className={cx(
                          styles.option,
                          active && styles.optionActive,
                          isSelected && styles.optionSelected,
                        )}
                        onClick={() => choose(option)}
                      >
                        {option.label}
                        {option.children?.length ? (
                          <ChevronRight className={styles.optionArrow} aria-hidden size={13} />
                        ) : null}
                      </button>
                    </li>
                  )
                })}
              </ul>
            ))}
          </div>
        </DismissableLayer>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: vz.space(1.5);
  min-width: 0;
}

.label {
  color: vz.color('foreground');
  font-size: vz.font-size('xs');
  font-weight: 500;
}

.trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(2);
  width: 100%;
  min-height: vz.space(10);
  padding: 0 vz.space(3);
  border: 1px solid vz.color('border');
  border-radius: var(--radius-lg);
  background: vz.color('card');
  color: vz.color('foreground');
  font: inherit;
  font-size: vz.font-size('sm');
  text-align: start;
  cursor: pointer;

  @include vz.focus-ring(2px, 0, 0.7);

  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }
}

.placeholder {
  color: vz.color('muted-foreground');
}

.chevron {
  flex: none;
  width: vz.space(4);
  height: vz.space(4);
  color: vz.color('muted-foreground');
  transition: transform vz.duration('fast') vz.ease('out');
}

.open {
  transform: rotate(180deg);
}

.panel {
  position: absolute;
  z-index: var(--z-popover);
  top: calc(100% + 4px);
  left: 0;
  display: flex;
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: var(--radius-lg);
  background: vz.color('popover');
  color: vz.color('popover-foreground');
  box-shadow: vz.elevation(3);
  min-width: 100%;
}

.column {
  min-width: 10rem;
  max-height: 17rem;
  overflow: auto;
  padding: vz.space(1);
  margin: 0;
  border-inline-end: 1px solid vz.color('border');
  list-style: none;

  &:last-child {
    border-inline-end: 0;
  }
}

.option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(2);
  width: 100%;
  padding: vz.space(2);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: vz.font-size('xs');
  text-align: start;
  cursor: pointer;
  white-space: nowrap;

  @include vz.hover {
    background: vz.color('accent');
  }

  &:disabled {
    opacity: 0.45;
    pointer-events: none;
  }
}

.option-selected {
  color: vz.color('primary');
  font-weight: 600;
}

.option-active {
  background: vz.color('accent');
}

.option-arrow {
  color: vz.color('muted-foreground');
}

@media (max-width: 40rem) {
  .panel {
    flex-direction: column;
  }

  .column {
    min-width: 100%;
    max-height: 12rem;
    border-inline-end: 0;
    border-block-end: 1px solid vz.color('border');
  }
}
